/* prog28_levenshtein.c
 *
 * Re‑implementation of the original obfuscated binary.
 * Computes the Levenshtein distance between two strings (max length 64).
 *
 * Behaviour:
 *   - If argc < 3          → prints "USAGE\n"
 *   - If any argument > 64 → prints "TOO_LONG\n"
 *   - Otherwise            → prints the distance followed by '\n'
 *
 * The program returns 0 in all cases.
 */

#include <stdio.h>
#include <string.h>

#define MAXLEN 64

int main(int argc, char *argv[])
{
    /* Argument validation */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *s1 = argv[1];
    const char *s2 = argv[2];

    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);

    if (len1 > MAXLEN || len2 > MAXLEN) {
        puts("TOO_LONG");
        return 0;
    }

    /* DP table: (len1+1) × (len2+1), but we allocate the full 65×65
       because the original binary used a fixed 0x41 (=65) stride. */
    int dp[MAXLEN + 1][MAXLEN + 1];

    /* Initialise first row and column */
    for (size_t i = 0; i <= len1; ++i)
        dp[i][0] = (int)i;
    for (size_t j = 0; j <= len2; ++j)
        dp[0][j] = (int)j;

    /* Fill the table */
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            if (s1[i - 1] == s2[j - 1]) {
                dp[i][j] = dp[i - 1][j - 1];               /* no cost */
            } else {
                int del = dp[i - 1][j] + 1;                /* deletion */
                int ins = dp[i][j - 1] + 1;                /* insertion */
                int sub = dp[i - 1][j - 1] + 1;            /* substitution */
                int min = del;
                if (ins < min) min = ins;
                if (sub < min) min = sub;
                dp[i][j] = min;
            }
        }
    }

    /* Output the result */
    printf("%d\n", dp[len1][len2]);
    return 0;
}
